insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 1, 'Valve 2 has no depth until valve 1 has one. How does the engine settle a depth that appears on both sides of its own equation?', '["It iterates a fixed point to 0.01 ft, because the trial depth sets the injection pressure and the injection pressure sets the next trial depth.", "It solves the whole string as a linear system once the stage pressures are known.", "It works upward from the target depth, so valve 1 only fixes the top of the string.", "It places valve 2 at the 250.0 ft minimum spacing below valve 1 without iterating."]'::jsonb, 0, 'The published westTexasOil case needs six iterates for valve 2, and the tolerance quoted is a depth tolerance rather than a pressure one.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 2, 'The valve 2 iteration on westTexasOil begins at the minimum spacing seed and its first step moves 1241.979455800 ft. What does a move that size establish?', '["That the recursion is unstable at its first step.", "That the kill fluid gradient was declared too light for this well.", "That the fixed point contracts hard, so the seed is a starting point and not an estimate.", "That the minimum spacing seed was badly chosen here, and a seed nearer the answer would have cut both the iterate count and the tolerance the engine can reach."]'::jsonb, 2, 'The moves that follow are 67.602379241 ft, then 3.673699643 ft, so the sequence loses roughly an order of magnitude at every step.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 3, 'At the converged trial depth for valve 2 on westTexasOil the injection pressure is 1080.184701047 psia and the transfer production pressure at valve 1 is 326.624999472 psia. What becomes of the 50.0 psi transfer differential in reaching a head of 703.559701575 psi?', '["It is divided by the kill fluid gradient before any subtraction.", "It is taken off once, together with the transfer production pressure at valve 1, from the injection pressure at that depth.", "It is added to the transfer production pressure at valve 1 and the sum is then multiplied by the 0.45 psi/ft kill fluid gradient to turn the balance into an interval in feet.", "It is charged once for every valve already placed, so it accumulates down the string exactly as the surface decrement does."]'::jsonb, 1, 'Dividing that head by the 0.45 psi/ft kill fluid gradient gives the interval, which is why a differential is paid in feet and not only in psi.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 4, 'Which surface pressure does the engine carry into the stage that places valve 8 on westTexasOil?', '["1014.7000 psia, the kickoff pressure, since the decrement applies to the valves already placed and not to the stage being placed.", "914.7000 psia, the operating pressure, because the deepest mandrel is the one that has to work once the unloading is finished.", "864.7000 psia, which belongs to the stage that placed the valve above it.", "839.7000 psia."]'::jsonb, 3, 'Every stage runs on the kickoff less the decrement times the count of valves already placed, so valve 8 sits seven steps of 25.00 psi below 1014.7 psia.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 5, 'A decrement sweep on westTexasOil returns a valve 1 depth of 2119.249955500 ft in every row. What accounts for that?', '["Valve 1 is set by the kickoff pressure against a full column of kill fluid, and no decrement has been applied at its stage.", "The minimum spacing of 250.0 ft pins the top of the string in place.", "The reported top valve depth is rounded before the sweep prints it.", "The sweep holds valve 1 fixed as a reference mandrel and re-spaces only the valves beneath it, which is what makes the shifts comparable between rows."]'::jsonb, 0, 'The same insensitivity means a decrement chosen for unloading reasons cannot be used to nudge a top valve that lands at an awkward depth.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 6, 'Running westTexasOil at 20.00 psi per valve rather than the published 25.00 psi per valve, how do the depth shifts against the published design behave down the string?', '["They stay constant, since every stage pressure moves by the same 5.00 psi.", "They compound downward, running 12.954034679 ft at valve 2 and reaching 162.471207387 ft at valve 6, because each valve inherits the displacement of the one above it and adds its own.", "They are largest at valve 2 and have decayed to nothing by valve 6.", "They are zero until the stop reason changes, then appear at the last mandrel."]'::jsonb, 1, 'At 50.00 psi per valve the shifts turn shallow, running -64.630249541 ft at valve 2 and -798.537137501 ft at valve 6, and they still compound.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 7, 'westTexasOil spaced at 50.00 psi per valve places 6 valves with no multipointing stage at all. What has been paid for that clean unloading?', '["The transfer differential, which the engine raises to compensate.", "Nothing measurable, because the stop reason stays targetDepth and the string reaches the same floor using fewer mandrels than the published run does.", "Depth, since the deepest mandrel lands at 6231.668461708 ft instead of reaching the 7500.000000000 ft floor.", "Valve integrity, because the wider stage steps push each valve further past its test rack opening pressure than the published design does."]'::jsonb, 2, 'At 15.00 psi per valve the same well multipoints at five stages and still reaches 7500.000000000 ft, so the sweep trades one against the other.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 8, 'How does the way a string pays for its transfer differential differ from the way it pays for its surface decrement?', '["The differential costs the same at every valve, while the decrement accumulates.", "The differential accumulates down the string while the decrement is charged once at the first mandrel, which is why raising it moves only the deepest valves.", "Both accumulate, so a design that doubles either of them loses head at the same rate and ends with the same number of mandrels either way.", "Neither accumulates, since the engine applies both of them to the kickoff pressure before the recursion starts and then holds that result fixed."]'::jsonb, 0, 'On westTexasOil the 50.0 psi differential is charged at all eight valves while the stage pressure has already fallen 175.0 psi by valve 8.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 9, 'constantPressurePPO runs a decrement of 0.00 psi per valve and sits at 1114.7000 psia through all six stages. What supplies the stage to stage change its recursion still needs?', '["Its 8500.0 ft target depth, which the recursion works back from.", "Its 800.0 Mscf/d gas target, felt through the weight of the annulus column.", "Its 0.42 psi/ft kill fluid gradient, which the constant pressure convention rescales at each stage so that the intervals keep shrinking down the string.", "Its 100.0 psi transfer differential, the only margin left once the surface pressure never falls."]'::jsonb, 3, 'Raising that differential shortens every interval below valve 1 on this case, which is the decrement lever pulled in a different place.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 10, 'In what sense are surface close and constant pressure one algorithm rather than two?', '["They agree at every mandrel once the differentials are matched.", "The engine sets the decrement to zero and runs the identical fixed point, with no separate spacing method anywhere in it.", "They share the top valve calculation and then branch into two closing criteria, which is why a constant pressure design reports a different set of stop reasons.", "They differ only in the order the valves are placed, since constant pressure works up from the target depth while surface close works down from valve 1."]'::jsonb, 1, 'That is why the published constantPressurePPO case carries a decrement input of 0.00 psi per valve rather than a method flag inside its spacing math.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 11, 'westTexasOil placed on constant pressure needs 6 valves against 8 on surface close. What happens to its unloading?', '["It improves, since fewer mandrels leave fewer valves that can be caught open.", "It is unchanged, because both conventions reach 7500.000000000 ft.", "It gets worse, multipointing at stages 2, 3, 4, 5 and 6 rather than at stages 2, 3 and 4, because a held surface pressure removes the mechanism that shuts the upper valves.", "It cannot be compared, since the two conventions stop for different reasons."]'::jsonb, 2, 'midDecrementKnifeEdge tells the same story, moving from four multipointing stages on surface close to five on constant pressure.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 12, 'Why do the published westTexasOil increments shrink from 1563.466503048 ft down to 131.375432376 ft?', '["The kill fluid gradient rises with depth as the column warms, so each psi of surplus head buys fewer feet at the bottom of the string than it does at the top.", "The injection gas grows heavier with depth, and that added weight is taken out of the head available to each successive mandrel until none of it is left.", "The 250.0 ft minimum spacing is applied progressively as the string lengthens, which compresses the intervals as they approach the target depth.", "The stage pressure drops by a fixed step per valve while the transfer pressure to be beaten rises with depth."]'::jsonb, 3, 'A string therefore runs out of room rather than out of valves: this case is allowed 12 valves and places 8 of them.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 13, 'Four conditions can end the spacing recursion. Which of them announces nothing of its own in the warning list?', '["The stage pressure falling to the unloading wellhead pressure.", "Reaching the target depth, the stop reason on the published westTexasOil run.", "Falling below the minimum spacing, which returns quietly because the engine treats it as an ordinary end to a string rather than as an exception.", "Running out of valves, since the valve limit is an input the designer chose and the engine assumes a chosen limit needs no remark."]'::jsonb, 1, 'Driving the same well to maxValves 5 raises valveLimit and driving it to 200.0 psi per valve raises shallowTarget, so three of the four stops speak up.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 14, 'On westTexasOil the valve 8 recursion converges to an increment of 206.016771390 ft from valve 7, against a stated minimum spacing of 250.0 ft, before the mandrel is pulled to its 7500.0 ft floor. What does the engine do with it?', '["It seats that mandrel on the floor, 131.375432376 ft from valve 7, and stops without ever testing the minimum spacing or raising a warning.", "It widens the interval back to the declared 250.0 ft minimum and places the valve there.", "It places the mandrel and records a minSpacing warning against it.", "It refuses the mandrel and ends the string at 7 valves on a minSpacing stop, which is the behaviour deepHighPressure shows when its own recursion asks for a valve inside a 300 ft minimum."]'::jsonb, 0, 'constantPressurePPO does the same thing, seating its last mandrel 152.956208919 ft from its neighbour against a stated 200.0 ft minimum.'),
  ('gaslift', 'intermediate', 'module', 'm01-spacing-is-a-recursion', 15, 'The minimum spacing check is real and it works, yet the golden file records perfect agreement on the two cases that skip it. How does that happen?', '["The golden file carries no spacing increments to compare.", "The oracle leaves the minimum spacing out of its input list.", "The independent oracle orders the same two branches the same wrong way, so on a target depth stop both sides skip the same test and the comparison between them is silent.", "The comparison tolerance is wider than the increment at issue."]'::jsonb, 2, 'deepHighPressure proves the check is live, stopping at 7 valves with its deepest mandrel 1855.337744624 ft short of its 10500.0 ft floor and raising the warning.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 1, 'In the force balance at the instant the stem lifts, which fluid acts on which area for an injection pressure operated valve?', '["The casing acts on the port area alone, while the tubing acts on the whole bellows area including the port beneath it.", "The casing acts on the bellows area less the port area, and the tubing acts on the port area.", "The casing acts on the full bellows area and the tubing acts on the port.", "Both fluids act on the full bellows area, and the port area enters only through the throughput calculation later in the chain."]'::jsonb, 1, 'A production pressure operated valve swaps those two roles, which is why one pair of helper routines covers both families.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 2, 'What condition shuts a gas lift valve once it is open?', '["The tubing pressure at depth falls below the test rack opening pressure.", "The casing pressure at surface falls below the 60 degF dome charge.", "The pressure difference across the port falls below the transfer differential the design declared.", "The pressure acting on the full bellows area falls back to the dome pressure at valve temperature."]'::jsonb, 3, 'Closing is simpler than opening because the port term drops out of the balance, so a closing pressure needs no port area at all.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 3, 'westTexasOil valve 1 wants a dome of 1021.076842603 psia and valve 5 wants 1042.530383853 psia, on the same 0.25 in port in the same 0.77 in2 bellows. What does the pair show?', '["A dome charge belongs to a depth, a stage pressure and a temperature rather than to the hardware.", "A dome charge is a spring rating that belongs to the valve, in the way a relief valve setting belongs to a relief valve, and the difference between these two figures is a rounding artefact of the recursion tolerance.", "The two valves must carry different port sizes, because a shared R would force a shared dome pressure at every depth in the string.", "The deeper valve needs the higher dome because dome pressure rises monotonically with depth down any string, which is what makes a rack sheet a descending list."]'::jsonb, 0, 'Ordering the deeper valve with the shallower valve''s charge does not give a slightly wrong valve, it gives a valve that opens at the wrong stage.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 4, 'A 0.25 in port gives R of 0.158346404 in one published case and 0.063749851 in another. What follows for how R should be quoted?', '["R can be quoted for a port size alone, because the ratio is fixed by the port and the bellows area only scales the load.", "One of the two figures must be wrong, since a 0.25 in port has a single flow area and therefore a single ratio wherever it is fitted.", "R has no meaning without the bellows it sits in, since it is the port area divided by that bellows area.", "R should be quoted against the valve outside diameter instead, because that is what the catalogue orders on and the bellows area follows from it."]'::jsonb, 2, 'The published cases carry a 0.31 in2 bellows and a 0.77 in2 bellows, and a 0.25 in port in each gives 1.188137263 and 1.068090618 as the test rack multiplier.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 5, 'Ask for a 0.625 in port and then a 0.75 in port in a 0.31 in2 bellows. What does one over one minus R return?', '["A warning on both, since the engine clamps R below one and refuses a port larger than its bellows.", "96.758816160 and then -2.352290089, because the algebra has no notion that a port cannot exceed the bellows around it.", "1.328755780 and then 1.553469026, rising smoothly.", "Zero on both, since the port area cancels once R passes unity."]'::jsonb, 1, 'The 0.31 in2 catalogue on the published case stops at 0.3125 in, and that stop is the designer''s guard rather than anything the engine enforces.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 6, 'What does the module refuse to do about the port to bellows ratio?', '["It never clamps R below one, never warns on a negative multiplier and never checks that a port exists for the bellows it is asked about.", "It refuses to compute R at all unless a catalogue is supplied, since the ratio only means something once the engine knows which ports the case allows.", "It refuses any port whose ratio exceeds one half.", "It refuses to report throughput once the multiplier turns negative."]'::jsonb, 0, 'The published cases each pair a catalogue with their bellows, 0.125 in through 0.3125 in on the 0.31 in2 valves and 0.25 in through 0.75 in on the 0.77 in2 ones.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 7, 'A designer opens the port up to 0.75 in on a 0.77 in2 bellows to gain throughput. What else has been changed?', '["Nothing but the throughput, since R enters the opening balance and the rack setting is dialled separately by the shop from the dome charge.", "The bellows area, because the engine scales it with the port so that R stays inside its fitted range.", "The valve temperature, since a larger port passes more gas and the engine cools the dome before charging it.", "R becomes 0.573748658 and the test rack multiplier 2.346033671, so every psi of dome charge becomes more than two psi at the rack."]'::jsonb, 3, 'The same port area that passes more gas also widens the pressure interval the valve stays open across, so a port choice is never only a throughput choice.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 8, 'The dome is sealed at a fixed volume. What quantity does the engine hold constant between the test rack and the valve?', '["Pressure divided by absolute temperature, with z left out because nitrogen is close enough to ideal over the range in question.", "The product of pressure and z, since the bellows deflection takes up whatever volume change the gas law would otherwise demand at depth.", "Pressure divided by z times absolute temperature, evaluated on nitrogen.", "The dome pressure itself, with the temperature entering only through the linear correction factor the older manuals print."]'::jsonb, 2, 'The nitrogen z values do real work over that range, running 0.979414628 at the rack against 0.988632778 at 120.0 degF on the shallowest published row.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 9, 'Across the published charges of 600.0, 800.0, 1000.0 and 1200.0 psia at rising valve temperatures, what happens to Ct?', '["It falls from 0.888133808 to 0.697487187, so a shop dialling one number for a shallow valve and a hot deep one has set two different valves.", "It rises towards unity as the dome warms and the gas moves further from ideal.", "It stays near 0.888 because the correction is dominated by pressure.", "It falls and then turns back up once nitrogen z passes unity."]'::jsonb, 0, 'Ct is the 60 degF charge divided by the dome pressure at valve temperature, so a smaller Ct means a larger downhole pressure for the same charge.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 10, 'Correcting 600.0 psia at 60 degF forward to 120.0 degF and then inverting the result returns the charge to 1.467e-11 psi. Why does that matter?', '["It shows the correction is exact, since a residual that small can only come from arithmetic rounding rather than from any physical assumption.", "It shows the pair is a genuine round trip rather than two independent approximations.", "It shows nitrogen is ideal at these conditions.", "It shows the linear rule of thumb and the real gas ratio agree at 120.0 degF, which is what makes either of them usable across the string."]'::jsonb, 1, 'The dome z uses Dranchuk and Abou Kassem with nitrogen criticals, so the correction is defensible within a stated window rather than measured against data.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 11, 'The older manuals correct a dome charge with one over one plus 0.00215 times the temperature rise above 60 degF. How does it behave across the published rows?', '["It is conservative throughout, always predicting a dome pressure above the real gas answer so that a valve set on it opens early rather than late.", "It is accurate at the hot end and drifts at the cold one, which is the opposite of what the deep valves in a string need from a correction.", "It changes sign, reading -0.2696 percent at 120.0 degF and 1.7904 percent at 250.0 degF.", "It tracks the real gas ratio to within a tenth of a percent everywhere."]'::jsonb, 2, 'At 250.0 degF the linear rule predicts 1690.200000 psia against a real gas 1720.461713 psia, a miss of 30.261713 psi on one valve.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 12, 'What makes the test rack opening pressure the one pressure at which a valve can be checked in a shop?', '["The rack applies the operating surface pressure to the casing side, which is the condition the valve has to hold once the well is on production.", "The rack holds the valve at its own downhole temperature, so the dome pressure it sees is the same one it will see in the well at its own depth.", "The rack is the only place the port area can be measured directly, and R has to be measured before any of the pressures in the chain can be worked out.", "The tubing side is open to atmosphere and the dome is back at 60 degF, so the balance loses a term and the opening is the charge over one minus R."]'::jsonb, 3, 'Everything downhole about the valve, its depth, its stage pressure and its temperature, has already been folded into the charge before a tester sees it.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 13, 'A shop dials 1021.076842603 psia onto the rack for westTexasOil valve 1 instead of 956.727988968 psia. What has gone wrong?', '["The dome pressure at valve temperature has been dialled in place of the rack opening, so the valve leaves the shop holding far too much.", "The 60 degF charge has been dialled in place of the rack opening.", "The closing surface pressure has been used instead of the opening pressure.", "The rack multiplier has been applied twice to the same charge."]'::jsonb, 0, 'The error is largest where the two columns are furthest apart, at the bottom of the string, which is exactly where an unloading failure costs the most time.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 14, 'Down westTexasOil the dome at valve temperature rises to valve 3 and then falls, while the rack openings fall from the first valve to the last without a reversal. What produces the turn?', '["The stage pressure, which falls by 25.00 psi a valve and therefore turns the dome column over once it has fallen far enough below the kickoff.", "The port selection, since the engine moves to a larger port at valve 3 and the changed R turns the dome column while leaving the rack column alone.", "The temperature correction, since deeper valves are hotter and a given rack charge buys more downhole pressure there.", "The kill fluid column above valve 3, heavy enough to reverse the production pressure there."]'::jsonb, 2, 'That is why a rack sheet reads as a tidy descending list while the pressures the valves actually see do not descend at all.'),
  ('gaslift', 'intermediate', 'module', 'm02-the-valve-itself', 15, 'westTexasOil valve 8 at 7500.000000000 ft and deepHighPressure valve 7 at 8644.662255376 ft are reported without a rack opening. Why?', '["They fell outside the port catalogue supplied with their case.", "They are orifices, so they have no dome, no rack setting and no closing pressure, and the engine reports only depths, the pressures either side and a throughput.", "They sit below the operating stage, so their rack settings would be meaningless and the engine suppresses them.", "They are charged valves whose rack settings were left out of the golden file."]'::jsonb, 1, 'A bottom orifice is a hole rather than a valve that always opens, which is a different claim and a weaker one.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 1, 'Setting one valve runs in a fixed order. What produces the dome pressure at valve temperature?', '["The nitrogen correction applied to the 60 degF charge the shop dialled, which is the step that turns a rack number into something the valve can be held to at depth.", "One over one minus R applied to the rack opening pressure, which is the step that carries a shop measurement back down the chain to the conditions at the mandrel.", "The force balance, fed by the pressures on both sides of the port and by R.", "The gas column march alone, carrying the stage surface pressure down to the valve depth and reporting the pressure it finds there as the dome the valve requires."]'::jsonb, 2, 'Every step in the chain consumes a number the step before it produced, so a missing depth stops the sequence before the dome is reached.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 2, 'westTexasOil valve 3 is set on 964.7000 psia rather than on the 914.7000 psia the well will operate at. Why?', '["A valve is set on the injection pressure its own stage shows at its own depth, because that is the moment it has to open.", "The operating pressure applies only to the valves below the operating stage, since those are the ones the well will still be leaning on once the unloading has finished.", "The stage pressure is the higher of the two, so it is the conservative choice.", "The operating pressure is reserved for the throughput calculation."]'::jsonb, 0, 'Setting on the operating pressure instead makes the error change sign down the string, soft above valve 5 and stiff below it, by amounts that grow with distance from that stage.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 3, 'A rack sheet arrives with opening pressures and no depths. What is wrong with working from it?', '["Nothing, since the rack opening is the one number the shop can verify.", "Two valves can share a rack opening and have nothing else in common, because the same charge lands at different dome pressures at different temperatures.", "The sheet omits R, which cannot be recovered from an opening pressure.", "The sheet is in psia and the well is worked in psig."]'::jsonb, 1, 'A rack sheet copied to a well with a different temperature profile is a different set of valves, whatever the numbers printed on it say.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 4, 'What does the setting chain refuse to establish about the depths it works at?', '["Whether the valve can pass the target gas rate, which is left to a separate throughput correlation applied after the string has been spaced.", "Whether the mandrels clear the casing couplings, which is why the minimum spacing input exists and why the engine warns when a string violates it.", "Whether the injection gas gravity is right for the annulus, which the engine treats as a fixed input and never checks against a measured composition.", "Whether the well flows at any of them, since there is no IPR and no multiphase outflow in the module."]'::jsonb, 3, 'The production pressures come from a straight unloading gradient of 0.1 psi/ft above 114.7 psia on that case, declared as an input rather than computed.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 5, 'An IPO valve and a PPO valve sit at similar depths in the published cases with the same 0.25 in port in the same 0.77 in2 bellows. Why is the PPO rack setting less than half the size?', '["Its dome answers to the tubing rather than to the casing, and the tubing at that depth is far the lower of the two.", "Its bellows is charged to a lower pressure by convention on production operated strings.", "Its port is measured on a different reference area, which halves R.", "Its stage pressure is held constant, which lowers every setting in the string."]'::jsonb, 0, 'The published figures are 956.727988968 psia against 392.734228645 psia, which are not slightly different settings, they are on different scales.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 6, 'Down the published PPO string the domes at valve temperature climb 409.797201414, 549.605506795, 670.260984966, 774.397901322, 864.285550601 and 875.996561503 psia. What are they tracking?', '["The casing pressure, which rises with depth because the injection gas column gets heavier as it is compressed on the way down the annulus.", "The kill fluid column, whose weight above each mandrel is what the dome has to balance while the string is still being unloaded.", "The tubing pressure, which rises with depth.", "The valve temperature alone, since the charge is fixed at the shop and the correction is the only thing left that can vary from mandrel to mandrel."]'::jsonb, 2, 'An injection operated string does the opposite, holding its domes just under a casing pressure that changes far less between mandrels.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 7, 'Every spread on the published constantPressurePPO string is negative, running from -52.249540846 psi at valve 1 to -31.296561503 psi at valve 6. How should that be read?', '["As a property of the production operated family.", "As a sign that the two sides have been swapped, because a spread is a pressure fall from opening to closing and cannot be less than zero.", "As the amount by which the casing exceeds the tubing at each mandrel, which is a real quantity and is worth reporting whatever sign convention it is printed under.", "As an artefact of the constant pressure convention, which holds the surface pressure and so leaves nothing for the valve to fall through between opening and closing."]'::jsonb, 1, 'The engine hands its spread helper the production pressure as the opening side and the casing as the other side, and on this well the casing runs far above the tubing at every valve.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 8, 'The negative PPO spreads and the closing test that judges a production operated string against the casing are counted as one defect. What makes them one?', '["A single choice of acting fluid feeds both, so repairing it repairs the spread sign and the closing verdict together.", "They appear on the same published case and on the same valves, which is enough to treat them as one entry in a defect list rather than as two.", "Both are consequences of the constant pressure convention rather than of the valve family, since a held surface pressure changes what every test in the string is measured against.", "Both come from the same golden file, so they share a provenance."]'::jsonb, 0, 'The closing surface pressure is obtained by inverting a dome that balances against the tubing up a casing gas column, which is the same swap seen from the other end.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 9, 'One symptom of that defect was reported and the other was not. Which was which, and what does the pair teach?', '["The negative spreads were reported and the closing verdict was not, because a sign error in a table is easier to spot than a verdict buried in a stage by stage sequence.", "Both were reported together, which is how the divergence was pinned as one root cause.", "Neither was reported until the oracle was written and the two sides disagreed.", "The closing verdict got reported and the negative spreads did not, so the simplest symptom is not always the one somebody notices."]'::jsonb, 3, 'A multipointing warning on every stage is loud in a design review, while a negative spread sat in the valve table needing no stages at all to see.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 10, 'A valve setting makes two claims. What are they, and why is the second reported separately?', '["That the valve opens at its stage and that it passes the target gas rate.", "That the valve opens at its own stage and that it is shut once the well is on production, and the second is reported apart because it can fail while the first holds.", "That the valve opens on the rack at the charge dialled and that it opens again at depth once the temperature correction has been applied to that same charge.", "That the valve clears the minimum spacing and that it holds the transfer differential above the valve sitting immediately over it in the string."]'::jsonb, 1, 'The engine carries the operating pressure only to answer the second question, which is why it plays no part in placing a mandrel or in setting a dome.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 11, 'westTexasOil is reported shut at 914.7 psia on valves 1 through 4 and open on valves 5, 6 and 7. What does the open flag say about those three?', '["That they were charged too softly and must be reset before the string is run.", "That the string will inject at four depths at once, which is the condition the multipointing warning exists to report on a design review.", "That the operating casing is above their domes, which is what the design intends below the operating stage.", "That their rack openings were computed from a stage pressure that no longer exists once the well has been handed over to the operating pressure."]'::jsonb, 2, 'The bottom orifice at 7500.000000000 ft has no dome, so the published case reports no closing surface pressure for it at all.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 12, 'deepHighPressure operates at 1314.7 psia and its valve 3 carries a closing surface pressure of 1313.798877081 psia. What should a reviewer take from that?', '["The flag is real but fragile, since a small change in the dome, the temperature profile or the gas gravity would move it.", "The valve is defective and needs a heavier charge.", "The design has failed, because a valve cannot sit that close to its operating pressure.", "The number is a rounding artefact of the closing column."]'::jsonb, 0, 'The valve above it clears by tens of psi and the valve below it misses by tens more, so valve 3 is the only one of the string sitting on the boundary.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 13, 'westTexasOil valve 4 opens on a rack setting of 912.433488084 psia and is judged shut downhole by a closing surface pressure of 918.986491277 psia. Why are those not the same claim?', '["The rack number is an opening pressure and the other is a closing pressure.", "The rack number is dialled with atmosphere on the far side, while the assertion is about a pressure at a depth with a live column on both sides.", "The rack number is quoted at 60 degF and the closing pressure at valve temperature, so the two differ by the nitrogen correction factor for that mandrel.", "The rack number carries the port area through R while the closing pressure does not."]'::jsonb, 1, 'Their closeness on this valve is a coincidence of position rather than a relation, and quoting the rack opening as the assertion is the common way to confuse them.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 14, 'The closing test can be run at valve depth or inverted to surface. On westTexasOil stage 3, valve 1 gives a depth margin of -5.671230322 psi and a surface margin of -5.355864496 psi. What follows?', '["The two roads disagree, so the verdict agreement for this design is false.", "The depth road is the only defensible one, since inverting a dome up a coarse gas column loses the precision the verdict needs at a margin of that size.", "Both roads return the same shut verdict, and agreement across all 8 stages of that design is true.", "The margins should match exactly, so the gap between them is an error."]'::jsonb, 2, 'The same stage keeps valve 2 open on both roads, at 10.525246278 psi of depth margin and 9.554898266 psi of surface margin.'),
  ('gaslift', 'intermediate', 'module', 'm03-setting-a-string', 15, 'All seven charged valves on westTexasOil carry the same 0.25 in port in the same 0.77 in2 bellows, yet the rack openings fall from 956.727988968 to 852.029990859 psia and the spreads from 47.285654927 to 10.738466038 psi. What are those trends?', '["Consequences of hardware, since the deeper mandrels carry smaller ports chosen to keep the throughput within the target the design declared.", "Consequences of the kill fluid column, which grows heavier down the string.", "Consequences of the temperature correction alone, which is the only quantity in the chain that changes between one mandrel and the next on a string of identical valves.", "Consequences of position, since the deep valve is the same valve set for a lower stage at a hotter depth."]'::jsonb, 3, 'Substituting one valve for a bigger port changes R, the dome the balance demands, the rack opening and the interval the valve stays open across, so a string that has had a valve edited in place was never computed.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 1, 'In terms of the force balance that sets the dome, what is a spread?', '["R times the difference between the pressures on the two sides of the port.", "The pressure interval between the test rack opening and the dome pressure at valve temperature, measured with atmosphere on the far side of the port.", "The difference between the stage surface pressure and the operating surface pressure, which is what the decrement removes from the casing at every unloading stage.", "A manufacturing tolerance on the bellows travel, quoted by the supplier for each port and bellows pairing listed in the catalogue."]'::jsonb, 0, 'Read the other way it is the gap from the opening pressure at depth to the dome at valve temperature, so 1068.362497529 psia against 1021.076842603 psia gives 47.285654927 psi.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 2, 'deepHighPressure valve 1 runs the smallest R of the three published cases and still reports 39.204722432 psi. Why?', '["A 0.31 in2 bellows carries more force than a 0.77 in2 one.", "Its injection pressure at depth of 1517.796497793 psia stands against a production pressure of 527.443159448 psia, so a small fraction of a very wide differential still comes out large.", "Its dome was charged at the rack rather than at valve temperature.", "Spread rises with depth, and that mandrel sits at 2606.192995401 ft."]'::jsonb, 1, 'R there is 0.039586601 against 0.063749851 on the other two published injection operated cases, so the ratio works against it and the differential wins anyway.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 3, 'Every charged valve of midDecrementKnifeEdge carries one 0.25 in port in one 0.77 in2 bellows, yet the spreads fall from 55.525309973 to 21.310451869 psi. What closed them?', '["R falls with depth because the bellows is squeezed by the higher casing pressure at the deeper mandrels, and a smaller ratio then takes a smaller share of the same differential.", "The dome charge was reduced valve by valve.", "The production pressure climbs with depth faster than the injection column gains, so the differential across the port narrows.", "Deeper mandrels carry a smaller port out of the catalogue."]'::jsonb, 2, 'No part changed anywhere down that string, and R is 0.063749851 on every one of those valves.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 4, 'westTexasOil valve 1 holds 47.285654927 psi of spread. Why is it still open when the next mandrel takes over?', '["The bottom orifice at 7500.000000000 ft has no dome and cannot close, so everything above it is held open by the casing pressure the design operates at through every stage.", "Its rack opening of 956.727988968 psia sits above the stage pressure, so the tester dialled a valve that cannot reseat until the casing is bled to the unloading wellhead pressure.", "Its dome sits above the injection pressure at depth.", "One stage of drop at its depth is 26.481994875 psi, which does not spend the spread, and two stages at 52.956885249 psi overspend it."]'::jsonb, 3, 'That is why the design carries a multipointing warning at stage 2, on a row reporting 20.803660052 psi of margin.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 5, 'deepHighPressure valve 1 carries more spread than midDecrementKnifeEdge valve 4 and shuts on time while the other does not. What settles it?', '["The drop each one meets: 43.324677700 psi against a 39.204722432 psi spread shuts the first, and 32.122462454 psi against a 32.272254090 psi spread leaves the second open by 0.149791635 psi.", "The smaller R, since a smaller ratio always closes a valve earlier.", "The knife edge case is spaced on the softer decrement of 26.75 psi per valve.", "The shallowest mandrel is always the first to shut in any string."]'::jsonb, 0, 'There is no threshold in a spread column: a spread is large or small only with respect to one other number, and that number lives in the stage table.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 6, 'westTexasOil is spaced on 25.00 psi per valve at surface. Why does its shallowest valve see 26.481994875 psi of drop?', '["The kill fluid gradient of 0.45 psi/ft is still standing in the annulus at that stage, and its weight is added to the decrement before any comparison against a spread is made.", "A lower stage pressure makes a lighter gas column, so it adds less weight over those 2119.249994721 ft and the loss at depth exceeds the loss at surface.", "The transfer differential of 50.0 psi is charged once per stage.", "Friction in the annulus adds to the surface loss."]'::jsonb, 1, 'Setting a spread against the decrement instead of against the drop at depth treats the budget as larger than it is.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 7, 'What does the margin column of an unloading stage table carry?', '["The difference between the closing surface pressure and the operating surface pressure, which is the same claim the shut flag makes for the finished well.", "The difference between the injection pressure at depth and the transfer production pressure at the mandrel above, which is the head that buys depth in the recursion.", "The spread less the drop accumulated at that valve''s depth.", "The gap between the test rack opening and the dome at 60 degF, which is what one over one minus R multiplies."]'::jsonb, 2, 'On westTexasOil valve 1 that gives 20.803660052 psi at stage 2 and -5.671230322 psi at stage 3, and the sign of it is the verdict.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 8, 'Down deepHighPressure the injection pressure at depth rises to 1552.882760861 psia at valve 3 and then falls away. Why does it turn?', '["The gas gradient falls with depth on that column because the linear geotherm outruns the compression, so beyond a certain point the column stops gaining weight and begins to lose it.", "The unloading gradient of 0.12 psi/ft is subtracted from the injection line once per mandrel, and by the third one the accumulated subtraction exceeds what the column adds.", "The port was changed at the fourth mandrel.", "Each mandrel sits a stage lower in surface pressure, and past that point the added depth stops paying for the 40.00 psi per valve it is charged."]'::jsonb, 3, 'The production side climbs steadily over the same rows, from 527.443159448 to 1213.736305005 psia, so the gap closes from both ends.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 9, 'On midDecrementKnifeEdge the post opening drops run 28.652797457 up to 33.355029522 psi while the spreads run 55.525309973 down to 21.310451869 psi. What does the crossing show?', '["Multipointing risk lives at the top of a string, where the spread is widest, and runs out with depth: the two columns cross between valve 4 and valve 5, and stages 6 and 7 are clean.", "That the deepest mandrel is the one most likely to hold two injection points open at once.", "That the design is under spaced and needs a larger decrement to reach its floor.", "That the two columns were built at different stages and cannot be compared."]'::jsonb, 0, 'The deep valves carry the opposite exposure, a narrow interval closed hard by the operating pressure and easily reopened by a casing excursion.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 10, 'One published string opens its top valve across 55.525309973 psi and another across 39.204722432 psi. Is the wider of the two the safer design?', '["Yes, since a wider interval keeps the valve open longer, and a valve that stays open longer hands the well down to the next mandrel with more of the kill fluid already displaced.", "No. The wider case multipoints at four stages, because its drops per stage are smaller too, and the two numbers of the pair only mean anything together.", "Yes, because a wider interval means a smaller R and a gentler dome.", "Neither, because spread is undefined on a charged valve."]'::jsonb, 1, 'deepHighPressure is charged 40.00 psi per valve against 26.75 psi on midDecrementKnifeEdge, so the narrower interval is the one meeting the larger drop.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 11, 'A stage table prints the same spread on every row for a given valve. What does that constant column mean?', '["It means R was recomputed at every stage and found unchanged, which is what a valve with no travel model is expected to report all the way through an unloading.", "It means the injection and production pressures at that depth held still through the unloading, since the interval is the difference between them scaled by the port to bellows ratio.", "It is the design condition value repeated, so it is a fixed budget and not evidence that the valve is unchanged.", "It means the valve is on the critical branch."]'::jsonb, 2, 'What actually moves stage to stage is the acting pressure at the valve, and the margin column is where that movement shows.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 12, 'Every valve of the published constantPressurePPO case reports between -52.249540846 and -31.296561503 psi. What does the sign say?', '["That the two sides were handed over in the wrong order.", "That a production operated valve genuinely opens on a falling pressure, so its interval is measured downward and reported below zero by convention.", "That the casing has been bled below the tubing at all six mandrels, which is what a constant pressure design does when the decrement is set to 0.00 psi per valve.", "That the dome was solved on nitrogen z outside the window the correlation is defensible in, which the module pins at Tpr 2.3 to 3.1 and Ppr 1 to 5."]'::jsonb, 0, 'A pressure interval a valve stays open across cannot be negative, so the sign settles it before any stage table is opened.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 13, 'Teaching well AKASO-3 is run as an injection operated string and then as a production operated one, on the same depths and the same 0.25 in port. What comes back?', '["A larger magnitude on the second run, since the tubing side carries the bellows.", "The same numbers, because the interval does not depend on the valve family.", "Nothing at all on the second run, since the helper refuses that family.", "Equal magnitudes with opposite signs, 48.150321911 psi at the top mandrel on the first run and -48.150321911 psi on the second, at one R of 0.063749851."]'::jsonb, 3, 'AKASO-3 is a teaching construct with no oracle behind it, and it exists so that one string can be run as either family.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 14, 'Why is a negative spread called the quieter half of one defect?', '["It shows up only once the unloading sequence has been run to the last stage, while the closing verdict is visible in the valve table straight away, so the louder symptom reaches a review first.", "It shares a root cause with the closing test being judged on the casing, it needs no stages at all to see, and nobody raised it.", "It is a rounding artefact of the dome temperature correction.", "It touches one of the six mandrels rather than all of them."]'::jsonb, 1, 'The pair is a pinned known divergence, left standing because the engine is consumed by a live application.'),
  ('gaslift', 'intermediate', 'module', 'm04-spread', 15, 'What does a positive spread still refuse to tell you?', '["The depth the valve belongs to, which has to be read out of the spacing recursion because the balance is run at a depth another mandrel chose and the sheet does not carry it.", "The dome pressure at valve temperature, which is reported separately because the correction runs on nitrogen z rather than on the linear rule of thumb the older manuals carry.", "Whether the valve passes what the well needs while open, since a real valve throttles on its stem and both of its pressures come off a shut in column.", "The port size, which is a catalogue choice."]'::jsonb, 2, 'There is no velocity and no injection rate in the annulus anywhere in the module, so it cannot say how long the valve takes to travel either.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 1, 'For the purpose of a throughput number, what is a gas lift valve?', '["A hole of known flow area with a pressure on each side.", "A bellows of known area balanced against a nitrogen dome, with the port acting as the restriction only once the stem has lifted clear of its seat.", "A choke whose capacity is read off the manufacturer''s coefficient for that part number and then corrected for the travel the stem has available.", "A spring loaded regulator on the casing."]'::jsonb, 0, 'The dome, the bellows and the stem play no part in the number at all, which is why one expression serves both valve families.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 2, 'How do the two pressures either side of the port enter the rate?', '["Through their difference, which is the differential a valve is sized on.", "Only through their ratio for the bracket, with the upstream pressure entering a second time on its own as a multiplier on the whole expression.", "Through the downstream pressure alone, once the port is choked.", "Through the square root of their product."]'::jsonb, 1, 'The rate also falls with the square root of the gas gravity and of the absolute upstream temperature, while rising with the flow area.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 3, 'Why can nothing useful be concluded by setting the 0.1875 in published row against the 0.5 in one?', '["One was computed on the critical branch and one on the subcritical branch, and since the engine clamps the ratio at 0.551208318 before the bracket, the two rows are not the same function.", "The 0.1875 in row is not a published golden value.", "They differ in three inputs at once: the port, the upstream pressure and the gas at its temperature.", "One of the two carries a portTooSmall warning."]'::jsonb, 2, 'The 0.1875 in row holds the highest upstream pressure in the table and passes the least of any critical row, because 0.027611654 in2 is the smallest area in it.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 4, 'A 0.25 in port at 1000.0 psia has its downstream pressure walked from 100.0000 to 500.0000 psia. What happens to the rate?', '["It falls steadily from 1255.291662 to 796.940795 Mscf/d, since every psi added below the port removes head from it.", "It rises, because a higher pressure below the port raises the gas density at the throat and a denser gas carries more standard volume through the same area.", "It falls by roughly a quarter, which is the share of the bracket the pressure ratio carries below the critical value.", "Nothing whatever."]'::jsonb, 3, 'Both those ratios sit below 0.551208318, so the gas leaves the port at the speed of sound and the downstream pressure cannot send information upstream.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 5, 'Why is the flat part of the curve exact rather than approximate?', '["The ratio is clamped at the critical value before the bracket is evaluated, so one expression covers both branches continuously.", "The choked branch is evaluated by a separate closed form that drops the downstream term entirely, and the two branches are blended over a short window either side so the join carries no step.", "It is measured rather than computed, because the four published rows were taken from a flow loop at the critical ratio and the engine interpolates between them below it.", "The specific heat ratio of 1.27 removes the downstream term."]'::jsonb, 0, 'The critical value of 0.551208318 follows from k, which is 1.27 here.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 6, 'On deepHighPressure valves 1 and 2 are critical and 3 through 7 are subcritical. What does that pattern share with the spread column?', '["Both are recomputed at every unloading stage, so both carry the acting pressure at the valve rather than a design condition, and both turn over where the injection line stops gaining.", "The two pressures close on each other with depth, so the deep valves sit on the sensitive branch.", "Both are properties of the port catalogue rather than of the string.", "Both reverse at the third mandrel because the temperature does."]'::jsonb, 1, 'midDecrementKnifeEdge shows the same shape one mandrel deeper, with valves 1, 2 and 3 critical and 4 through 7 subcritical.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 7, 'Why is it wrong to quote the throughput of a deep valve as a fixed capability?', '["A deep mandrel is an orifice with no dome, so no rate is reported for it.", "Rate is only defined for the valve at the point of injection.", "A subcritical valve loses rate as the tubing pressure wanders, and the module does not compute the tubing pressure at all, because the flowing traverse is passed in from outside.", "The catalogue changes below the operating stage."]'::jsonb, 2, 'midDecrementKnifeEdge valve 6 passes 1347.108582683 Mscf/d at a ratio of 0.734747861, and every psi on the production side moves that number.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 8, 'What is the discharge coefficient of 0.865 doing in the expression?', '["Allowing for the stem sitting in the port below full lift, which is the restriction the equation would otherwise miss on a partly open valve.", "Carrying the specific heat ratio of 1.27 into the bracket, so that the critical pressure ratio of 0.551208318 comes out of the same constant.", "Converting the flow area from square inches onto the standard volume basis the rate is reported on.", "Correcting an ideal nozzle to a real hole."]'::jsonb, 3, 'It is the whole of the correction for a real hole, and nothing else in the expression knows the valve is not a nozzle.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 9, 'Every charged valve of midDecrementKnifeEdge carries a 0.25 in port and the column runs 1529.098759722, 1534.198233515, 1529.067116144, 1505.775891086, 1440.849796778 and 1347.108582683 Mscf/d. Why does it fall?', '["The upstream pressure is still climbing over part of that string while the ratio and the temperature work against it.", "The catalogue steps down with depth, because selectPort walks upward from the smallest port and a deeper mandrel meets its target on a smaller one, so the area shrinks with no change of part number.", "The gas gravity rises with depth as the heavier components drop out of the injection stream, and the rate falls with the square root of the gravity at every mandrel below the first.", "The bellows area changes down that string."]'::jsonb, 0, 'A throughput column that falls with depth is the normal shape and not a fault.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 10, 'Against a 500.0 Mscf/d target the catalogue candidates on westTexasOil valve 1 pass 1359.548519 through 12235.936675 Mscf/d. Which port is taken?', '["The 0.3125 in port, because the rule keeps a margin of one catalogue step above the smallest port that clears, so a design does not sit on the edge of a portTooSmall warning.", "The 0.25 in port, because the rule walks the catalogue upward and stops at the first one that clears the target.", "The largest one, since 12235.936675 Mscf/d is the safest choice.", "Whichever candidate sits closest to 500.0 Mscf/d."]'::jsonb, 1, 'All seven candidates are critical at a ratio of 0.305724876, so the target could move a long way without changing the answer.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 11, 'The stage 5 surface margin on midDecrementKnifeEdge reads 0.124769727 psi at 400, 1000 and 1400 Mscf/d and then 15.249903355 psi at 1600. What shape is that?', '["A smooth curve sampled too coarsely to show its curvature.", "A discontinuity in the closing test at the operating pressure.", "A step function, because the design gas rate reaches the verdict only through selectPort, and between catalogue steps there is no dependence on it at all.", "Noise from the 0.01 ft tolerance the depths are iterated to."]'::jsonb, 2, 'The 1400 Mscf/d row already moves valve 6 onto a 0.3125 in port and the margin does not budge, because the stage 5 verdict hangs on valve 4.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 12, 'Why would halving the step size on the design gas rate axis not find the flip any sooner?', '["The flip is a closing verdict evaluated at surface on an inverted gas column, so a finer rate axis moves that inversion by less than the tolerance the column is marched to.", "The engine caches the port list between runs on one design.", "That axis is logarithmic below 1600 Mscf/d.", "There is no curve to resolve. The sensitivity lives in a catalogue, so the sweep that finds it has to run over the ports."]'::jsonb, 3, 'One port at a time gives 0.124769727 psi at 0.25 in, 15.249903355 at 0.3125 in, 33.744341944 at 0.375 in, 55.613320820 at 0.4375 in and 80.863315289 psi at 0.5 in.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 13, 'In what way is a fine sweep of that axis worse than a coarse one?', '["It costs more runs for the same answer, and each run repeats the whole spacing recursion, so the depths are recomputed from the top of the string at every point on the axis.", "It finds nothing between the steps and calls the design insensitive with more points behind it, which feels like evidence.", "It samples inside the catalogue steps, where the margin is undefined rather than constant, so the values it returns are artefacts of the iteration and cannot be compared.", "It crosses the portTooSmall warning more often."]'::jsonb, 1, 'The derivative is zero almost everywhere and undefined where it is not, so any slope quoted in psi per Mscf/d is an artefact of the two points that happened to be sampled.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 14, 'Every charged valve of deepHighPressure passes its 250.0 Mscf/d target and four of the six are open at 1314.7 psia. What does that show?', '["That the target was set too low for the string, since a valve passing its target comfortably could have taken a smaller port whose dome would then have closed it.", "That the two columns disagree, so one of them has been computed on the wrong acting fluid for this family of valve.", "Passing and closing are separate questions.", "That the design carries a multipointing warning at every stage above the point of injection, which the pass column is what raised."]'::jsonb, 2, 'The two columns share the port size and nothing else, since the shut flag comes from the dome, the temperature at depth and a gas column inverted to surface.'),
  ('gaslift', 'intermediate', 'module', 'm05-throughput', 15, 'A rate looks tight, so the port is opened up. What else has been changed?', '["Nothing else, since the port enters the rate only through its flow area.", "The regime, since a larger port always moves a valve onto the subcritical branch.", "The design gas rate, which is recomputed from the chosen port.", "R, and with it the dome the balance demands, the closing pressure and the interval the valve stays open across: taking midDecrementKnifeEdge to 0.3125 in throughout gains it a multipointing stage."]'::jsonb, 3, 'The stage 5 surface margin on valve 4 moves from 0.124769727 to 15.249903355 psi on that change, so one column was improved and the design was altered.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'What single claim sits underneath all five modules of this tier?', '["A string is one recursion that fixes the depths and one force balance run at each of them, and every setting is downstream of both.", "A valve is a bellows, a dome and a port, so once its three areas are known every number on the sheet follows from the catalogue the port was taken out of and from nothing else.", "Each valve is set on its own and then checked against its neighbours.", "The surface decrement is the only input that matters."]'::jsonb, 0, 'That is why changing an input near the top leaves the sheet below it wrong without looking wrong.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'A design is re-run on a different decrement and the top mandrel has moved. What has that caught?', '["Nothing, since every mandrel moves when the decrement moves.", "Something upstream of the recursion changed, because the shallowest valve is placed on the kickoff pressure against a full column of kill fluid before any decrement has been applied to anything.", "A minimum spacing violation at the shallow end of the string.", "The recursion failing to reach its 0.01 ft tolerance."]'::jsonb, 1, 'Taking westTexasOil from 25.00 to 20.00 psi per valve moves valve 6 by 162.471207387 ft and the top mandrel by 0.000000000 ft.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'At what point in the chain that produces a rack opening is the port to bellows ratio needed?', '["At the very start, because the port and the bellows are catalogue choices that have to be fixed before the spacing recursion can be handed a design gas rate to size against.", "At the very end, where one over one minus R turns the 60 degF charge into a rack opening, which is the only place in the whole chain the ratio is used at all.", "After the depth, the temperature and the pressures on both sides of the port, and before the dome at valve temperature is solved.", "Nowhere, since the ratio belongs to the throughput calculation."]'::jsonb, 2, 'Quoting the ratio with no bellows named is one of the failures to expect, because a 0.25 in port gives 0.063749851 in one bellows and 0.158346404 in another.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Why does the order of work take the temperature at every depth before any dome is touched?', '["Because the temperature profile is an input to the spacing recursion, so the depths it returns cannot be trusted until that profile has been checked against the geotherm.", "Because the nitrogen correlation is defensible only inside a pinned window, so the valve temperatures decide whether a dome may be reported for the valve at all.", "Because the port catalogue is indexed on temperature, so no port can be selected until the depths have been turned into valve temperatures.", "Every dome number is a temperature reading in disguise."]'::jsonb, 3, 'A 1000.0 psia charge dialled at 60 degF reads 1355.233465958 psia at 220.0 degF, and the linear rule of thumb misses that by -11.233466 psi.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Why does the order of work forbid reading the chain backwards from a rack setting?', '["Two valves can share a rack opening and have nothing else in common, because one charge lands at different domes at different temperatures.", "Because the rack opening is the one number in the chain the engine does not compute, so it has to be dialled by a tester and read back into the design before anything below it can be set.", "Because one over one minus R turns negative once the port is larger than the bellows it sits in, so an inverted chain can return a charge below atmospheric pressure with no warning raised.", "Because a rack opening is quoted in psia and a dome is not."]'::jsonb, 0, 'A rack sheet without depths is not a design, and a rack sheet copied to a well with a different temperature profile is a different set of valves.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Which failure does a production operated valve table invite?', '["Reading its domes as too low, since a production operated dome tracks a tubing pressure that rises with depth and so climbs down the string rather than turning over the way the other family does.", "Reading its numbers as though the acting fluid were the casing, when the dome on that family is balanced against the tubing.", "Reading its rack openings without the bellows they were multiplied on.", "Reading its throughput without the regime beside it."]'::jsonb, 1, 'On the published case the casing side clears by 379.101060 to 724.986977 psi while the rule that should judge it misses by 31.822047 to 52.249541 psi.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Why must the whole string be spaced before any valve is set?', '["Because the temperature profile is only available once the floor has been reached.", "Because the port catalogue cannot be read until the stop reason is known.", "Every setting consumes a depth, and that depth is chosen by the mandrel above, so a dome, a rack opening or a spread computed early is a number about a mandrel that may still move.", "Because the engine refuses to report a dome before a stop reason."]'::jsonb, 2, 'Spacing first also produces the two things worth writing down once and only once, the stop reason and the last spacing increment.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'A design stops on targetDepth. What is worth checking by hand?', '["The multipointing stage list, since a target depth stop puts the deepest mandrel on the floor and that mandrel is the one an unloading sequence is most likely to leave open.", "The closing surface pressure of the deepest charged valve, because a floor mandrel is set on the lowest stage pressure in the design and clears the operating pressure by the least.", "The gas gravity used in the annulus column, which that branch takes from the surface conditions rather than from the declared profile.", "The last spacing increment."]'::jsonb, 3, 'The branch returns before the minimum spacing is tested, so westTexasOil lands a mandrel 131.375432376 ft from its neighbour against a stated 250.0 ft with no warning raised.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'What is the subtraction check on a finished valve sheet?', '["The spread must equal the injection pressure at depth less the dome at valve temperature, since the two are the same number by construction.", "The rack opening must equal the 60 degF charge divided by one minus R, and a mismatch there is the temperature correction rather than the arithmetic, because the nitrogen round trip closes tightly.", "The drop at depth must equal the surface decrement, since both are one pressure loss read at two places on a single static gas column of a declared gravity.", "The dome must sit above the injection pressure at depth."]'::jsonb, 0, 'On westTexasOil valve 1 that is 1068.362497529 psia against 1021.076842603 psia giving 47.285654927 psi, and a mismatch is your arithmetic rather than the engine''s.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Why is comparing a spread with the surface decrement on the failure list?', '["The decrement is a spacing input and a spread is a valve output, so the two are built on different gas columns, one isothermal and the other on the linear geotherm the design declares.", "The drop a valve actually meets is at its own depth and it is larger, 26.481994875 psi against 25.00 psi per valve on westTexasOil.", "A decrement is charged once per string rather than once per stage.", "A spread is a differential and a decrement is an absolute pressure."]'::jsonb, 1, 'A lower stage pressure makes a lighter column, so it adds less weight over the interval and the loss at depth exceeds the loss at surface.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'A reviewer is handed a rate of 1347.108582683 Mscf/d with nothing beside it. What cannot be done with that figure?', '["It cannot be converted onto a standard volume basis.", "It cannot be used, since it exceeds any realistic design gas rate.", "It cannot be checked, compared with another valve or reproduced, because the regime and the differential it was computed at are what say which branch of the expression produced it.", "It cannot belong to a charged valve, only to a bottom orifice."]'::jsonb, 2, 'That valve sits at a ratio of 0.734747861, well above the critical 0.551208318, so the number moves with every psi on the production side.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'A review is handed a gas rate sensitivity in psi per Mscf/d. Why is the figure meaningless?', '["A verdict is a boolean and a boolean carries no derivative at all, so a number in those units has been taken across a change of state rather than along a curve that could hold a slope.", "Design gas rate is an input to the spacing recursion and moves every depth.", "The units do not reduce, since a margin is a pressure and a rate is a volume.", "The rate reaches the verdict only through the port catalogue, so what it moves along is a step and the derivative is zero almost everywhere."]'::jsonb, 3, 'Sampling that axis more finely returns more points that agree with each other, which is worse than a coarse sweep because it feels like evidence.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'One iteration converges from a seed over a thousand feet out while a finer sweep of another axis never finds anything. What separates the two cases?', '["The first is run to a stated tolerance while the second declares none, so only the first can report that it has stopped moving and the second can say nothing about its own resolution.", "One is a contracting fixed point where refining measures a real convergence, and the other has no curve in it to refine.", "The first is checked against a published golden and the second is not, so only one of the two has an independent oracle standing behind the numbers it returns.", "The two are run on different gas columns."]'::jsonb, 1, 'Refining and watching is the measurement that tells the cases apart, and anyone who expects every method to be suspect never learns which case is in front of them.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'What does a single edited row in a finished valve sheet leave you holding?', '["A design correct for every valve above the edited row and stale only below it, which is the usual and acceptable consequence of any local change to a sheet.", "A design whose stop reason and warning list have to be read again, since those two are the only outputs describing the run rather than the string.", "A design that was never computed.", "A design carrying a port that no longer matches its bellows, which is the one inconsistency the module does raise a warning about."]'::jsonb, 2, 'A bigger port changes R, then the dome, then the rack opening and the interval the valve stays open across, and moving a mandrel to miss a coupling does the same through a different door.'),
  ('gaslift', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What does this tier stop short of?', '["Setting a valve, which needs a temperature profile it does not carry.", "Spacing a string, which is left to the spacing module alone.", "Reporting a spread, which has no meaning until a stage table exists.", "Walking a string down: the stage by stage unloading, the point of injection and the margins those verdicts sit on are all left to the tier after it."]'::jsonb, 3, 'Nothing set here is superseded there: the depths still come from a recursion and a throughput is still an upper bound.'),
  ('gaslift', 'intermediate', 'final', null, 1, 'An engineer changes the decrement on a finished westTexasOil design from 25.00 to 20.00 psi per valve and keeps the rack sheet already issued, on the grounds that only depths were affected. What is the objection?', '["Depth fixes the temperature and both pressures at every port, so each dome and each rack opening below the top mandrel is now stale, and valve 6 alone has moved 162.471207387 ft.", "None, since the rack opening comes from the 60 degF charge divided by one minus R, and no depth appears in either quantity.", "The stop reason turns from targetDepth into minSpacing, which is what invalidates the sheet.", "Only the deepest charged valve needs reissuing, since the decrement is applied once per stage and its accumulated effect above the bottom mandrel stays inside the iteration tolerance."]'::jsonb, 0, 'The published shifts at 20.00 psi per valve grow from 12.954034679 ft at valve 2 to 162.471207387 ft at valve 6, because each mandrel inherits the displacement of the one above it and adds its own.'),
  ('gaslift', 'intermediate', 'final', null, 2, 'A team wants fewer multipointing stages and argues that raising the decrement by a few psi per valve buys every valve that same number of psi of extra drop against its spread. Where does the argument break?', '["Nowhere in principle, although the effect is masked because the transfer differential is subtracted from the same head at every mandrel and cancels the extra drop out again.", "It breaks because the decrement never reaches the valves at all, since each stage pressure is recomputed from the kickoff pressure and the kill fluid gradient rather than carried down the string.", "The drop a valve is judged on is measured at its own depth, and it exceeds the surface step because a lower stage pressure carries a lighter gas column, so westTexasOil valve 1 sees 26.481994875 psi against 25.00 psi at surface.", "It breaks only for the top mandrel, whose depth the decrement cannot move."]'::jsonb, 2, 'The excess of the drop at depth over the surface step is not a constant either, so the same surface change lands differently on every valve in the string.'),
  ('gaslift', 'intermediate', 'final', null, 3, 'A reviewer notes that the valve 8 recursion on westTexasOil had already settled at an increment of 206.016771390 ft, inside the stated 250.0 ft minimum, before the mandrel was seated on the 7500.0 ft floor, and that the golden file records exact agreement for that case. What does the passing golden establish?', '["That the minimum spacing rule was applied and satisfied, because a golden comparison covers every branch the routine contains.", "That the engine and its oracle order the same two branches the same way, and nothing more, since the target depth branch returns before the spacing test on both sides.", "That the oracle applied the rule and the engine skipped it, which is why the recorded increment falls short of the declared minimum while the comparison still passes on the depths themselves.", "That the declared minimum spacing is advisory rather than binding, and the golden encodes that intent by comparing depths without reference to the increment between them."]'::jsonb, 1, 'deepHighPressure shows the check working, stopping at 7 valves and raising a warning while still 1855.337744624 ft above its floor, so the rule is real and simply never reached on the target depth cases.'),
  ('gaslift', 'intermediate', 'final', null, 4, 'A compressor can hold a steady casing pressure but cannot bleed and hold a fixed step between stages, so a constant pressure design is proposed for a well previously spaced on surface close. What follows for the string?', '["A second spacing algorithm is used, with its own closing criterion in place of the transfer differential.", "The valve count rises, because holding the surface pressure leaves less head for each successive mandrel and the increments shorten faster down the string.", "The top mandrel moves deeper, since it is now placed on an undecremented surface pressure rather than on one already reduced by the first stage of bleed.", "The mechanism that shuts the upper valves is gone, so the target is reached in fewer and wider steps and the well multipoints at more stages, 2 through 6 on westTexasOil rather than 2 through 4."]'::jsonb, 3, 'The engine runs the identical fixed point with the decrement set to zero, which is why the published constantPressurePPO case carries a decrement input of 0.00 psi per valve rather than a separate method.'),
  ('gaslift', 'intermediate', 'final', null, 5, 'Asked to add margin to a constant pressure design, a junior engineer proposes raising the transfer differential, describing it as a safety factor. What does the change actually do?', '["It shortens every increment below the top mandrel, because the differential is subtracted once at each valve from the head that buys depth, so it is the same lever as the decrement pulled somewhere else.", "It leaves the depths alone and only widens the interval each valve stays open across.", "It raises the stage pressures, since the differential is added back to the surface pressure carried into the next stage before the gas column is marched down to the trial depth.", "It deepens the string, because a larger required margin over the tubing forces the recursion to search further down before the injection line can satisfy it at all."]'::jsonb, 0, 'On constantPressurePPO the differential of 100.0 psi is the only source of stage to stage change the recursion has, since the decrement there is 0.00 psi per valve.'),
  ('gaslift', 'intermediate', 'final', null, 6, 'A mandrel is shifted several tens of feet to clear a casing coupling after the string has been spaced and set. Which parts of the design survive the move?', '["All of them, provided the shift stays inside the declared minimum spacing.", "Only the top mandrel survives, since a shift anywhere in the string changes the kickoff pressure that placed valve 1 and therefore the datum every other depth was measured against.", "The valves above the moved mandrel survive, while that valve and every one below it do not, because depth sets the temperature and both port pressures that produce each dome.", "The rack openings survive and the closing pressures do not, because the rack number is dialled with atmosphere on the far side and is therefore free of any dependence on the temperature at depth."]'::jsonb, 2, 'A local looking change on a sheet that lists valves in rows is a change to a chain, and the module reports no staleness of any kind.'),
  ('gaslift', 'intermediate', 'final', null, 7, 'A design stops on minSpacing short of its target depth, so the design gas rate is raised in the hope of reaching the floor. What does the rerun return?', '["A deeper string, because a larger target pushes the selected port up the catalogue and the wider port passes more head to the next mandrel.", "The same depths and the same stop reason, since the gas rate reaches the design only through port selection and the spacing recursion never sees it.", "A deeper string with the same valve count, since the extra throughput lets each valve hold its stage against a smaller transfer differential and the recursion buys depth with the difference.", "An unchanged string with a portTooSmall warning attached, which is the only route by which a gas rate can alter a spacing result."]'::jsonb, 1, 'The spacing list holds the kickoff pressure, the operating pressure, the unloading wellhead pressure, the two gradients, the differential, the decrement and the method, and the gas rate is in the valve list instead.'),
  ('gaslift', 'intermediate', 'final', null, 8, 'A 0.77 in2 valve is respecified from a 0.25 in port to a 0.75 in one and the shop is asked to dial the rack opening from the same dome charge. What has changed besides the throughput?', '["Nothing else, since R enters the rack opening and the throughput separately and the two effects do not interact.", "The dome charge itself has to fall to hold the same opening pressure at depth, which is the only change, and the interval the valve stays open across is fixed by the bellows area alone.", "The multiplier turns negative, because a 0.75 in port has a flow area larger than the bellows it is asked to sit in and one minus R changes sign.", "R goes from 0.063749851 to 0.573748658, so the rack multiplier goes from 1.068090618 to 2.346033671 and the interval the valve stays open across widens with it."]'::jsonb, 3, 'Spread is R times the differential across the port, so a port change moves the closing behaviour of the valve at the same time as it moves the rate it can pass.'),
  ('gaslift', 'intermediate', 'final', null, 9, 'A stores clerk fills a replacement valve for the fifth mandrel of westTexasOil using the charge recorded against the shallowest one, the hardware being identical. What has been put in the well?', '["A valve that opens at the wrong stage, since 1021.076842603 psia belongs to a depth of 2119.249994721 ft and the fifth mandrel wants 1042.530383853 psia at 6530.440469862 ft.", "A valve slightly soft on its opening pressure but correct on its closing pressure, because closing is set by the bellows area alone.", "The correct valve, because both mandrels carry the same 0.25 in port in the same 0.77 in2 bellows at the same R of 0.063749851, and R is what fixes the setting.", "A valve that will not open at any stage, since the charge recorded for the shallowest mandrel is the highest in the string and no later stage pressure can reach it at depth."]'::jsonb, 0, 'A dome charge belongs to a depth, a stage pressure and a temperature, in the way a relief valve setting does not.'),
  ('gaslift', 'intermediate', 'final', null, 10, 'A shop is handed one nitrogen charge and asked to use it for two valves in the same string, one landing at a valve temperature of 120.0 degF and the other at 250.0 degF. What has the shop produced?', '["Two identical valves, since the dome is sealed at fixed volume and its charge is therefore conserved.", "Two valves differing only in their rack openings, because the temperature correction is applied after one over one minus R rather than before it.", "Two different valves, since the pressure the same charge exerts downhole rises with temperature and Ct falls from 0.888133808 to 0.697487187 between those two rows.", "Two valves whose openings at depth differ by the ratio of the absolute temperatures alone, since nitrogen is close enough to ideal across that range for z to be dropped from the correction."]'::jsonb, 2, 'The engine holds pressure over z times absolute temperature constant and solves it on nitrogen z, which reaches 1.020827392 on the hottest published row.'),
  ('gaslift', 'intermediate', 'final', null, 11, 'A field engineer defends the older correction of one over one plus 0.00215 times the temperature rise above 60 degF as conservative, on the grounds that it is nearly exact at 120.0 degF. Why is the defence wrong?', '["The rule is always optimistic, so its errors accumulate in one direction down a string and a deep valve is set soft by the sum of them.", "The rule is exact only for air, and applying it to a nitrogen dome carries an additional bias set by the ratio of the two molecular weights.", "The rule is conservative in pressure but not in temperature.", "The error changes sign, running -0.2696 percent at 120.0 degF and 1.7904 percent at 250.0 degF, so there is no margin in it, only a temperature at which it happens to be right."]'::jsonb, 3, 'On the hottest published row the linear rule misses the dome at temperature by -30.261713 psi, and deep valves are exactly where a wrong dome costs the most.'),
  ('gaslift', 'intermediate', 'final', null, 12, 'A rack multiplier of 1.188137263 is carried over from an earlier job onto a valve with the same 0.25 in port sitting in a 0.77 in2 bellows. What does the copied figure do to the setting?', '["Nothing, because the multiplier depends on the port and both valves carry the same port.", "It leaves the valve stiff, since that multiplier belongs to a 0.31 in2 bellows at an R of 0.158346404, while the correct pairing gives 0.063749851 and 1.068090618.", "It leaves the valve soft, because the larger bellows occupies more of the force balance and the correct multiplier for it exceeds the one that was copied across from the smaller one.", "It moves the rack opening and the dome at valve temperature together, so the opening pressure at depth is preserved and only the number on the tester''s gauge is wrong."]'::jsonb, 1, 'R is the fraction of the bellows the port occupies, so quoting either R or a multiplier without naming the bellows says nothing at all.'),
  ('gaslift', 'intermediate', 'final', null, 13, 'A valve is re-domed to a higher charge so that it opens later in the unloading, with the string otherwise untouched. What else moves with it?', '["Nothing else, since opening and closing are set by different areas.", "The spread, which widens by the same number of psi the charge was raised by, since spread is measured from the opening pressure down to the dome and only one end has moved.", "Its closing pressure, because the valve shuts when the pressure on the full bellows area falls back to the dome at valve temperature, so the casing at which it is judged shut rises too.", "The throughput, since the rate is evaluated at the differential the valve holds when open and a stiffer dome holds a larger one."]'::jsonb, 2, 'The closing test is the second and separately reported claim a setting makes, and it can fail while the opening claim holds.'),
  ('gaslift', 'intermediate', 'final', null, 14, 'A supplier offers to quote dome charges before the depths are settled, proposing to fit the string to the valves rather than the other way round. What is the objection?', '["None, provided the bellows area and the port catalogue are fixed first.", "The objection is commercial rather than technical, since the same charge can be dialled onto any bellows once one over one minus R has been applied to it.", "The balance needs the injection and production pressures at the valve''s own depth and the temperature there, and the recursion has not produced any of them yet.", "The objection is that the supplier would have to assume a decrement, which is the one input the engine derives for itself from the kickoff pressure and the compressor limit."]'::jsonb, 2, 'Neither published dome charge is a round number, which is the visible sign that each was produced by a depth rather than chosen from a range.'),
  ('gaslift', 'intermediate', 'final', null, 15, 'A shop sets an entire westTexasOil string on the 914.7000 psia the well will operate at instead of on each valve''s own stage pressure. How does the resulting error behave down the string?', '["It is one sign throughout and grows with depth, since the operating pressure is below every stage pressure in the design.", "It changes sign, leaving valves 1 through 4 too soft and valves 6 through 8 too stiff, by amounts that grow with distance from the operating stage.", "It is confined to the charged valves nearest the bottom, because the stages there differ most from 914.7000 psia and the ones above sit inside the tolerance the iteration converges to.", "It cancels out over the string as a whole, because the operating pressure is the arithmetic mean of the eight stage pressures and the errors either side of it are symmetric."]'::jsonb, 1, 'Each valve is set on the injection pressure its own stage shows at its own depth, since that is the moment it has to open, and the operating pressure answers a different question entirely.'),
  ('gaslift', 'intermediate', 'final', null, 16, 'A production operated design returns multipointing warnings at stages 2 through 6, and the reviewer proposes to respace the string to clear them. What is wrong with that plan?', '["The verdict is a pinned known divergence, because the closing pressure of a tubing balanced dome is inverted up a casing column and then compared with the casing, so the respacing would be chasing an artefact.", "Nothing, since a warning at five consecutive stages is the standard signal that the decrement is too small.", "Respacing cannot clear multipointing under any convention, because the warning is raised whenever two valves are open and a string always passes through such a stage.", "The plan is sound but incomplete, since the closing test would also have to be rerun at valve depth to confirm that the new spacing has moved the margins in the intended direction."]'::jsonb, 0, 'On that case the casing side clears by 379.101060 to 724.986977 psi while the tubing side rule misses by 31.822047 to 52.249541 psi, so the two sides do not merely differ in size, they differ in verdict.'),
  ('gaslift', 'intermediate', 'final', null, 17, 'A proven rack sheet is transferred to a second well drilled to the same depths but running a hotter temperature profile. What has actually been transferred?', '["The same valves, since the rack opening is measured with atmosphere on the far side and is therefore free of the well.", "The same valves with a small bias, correctable by the linear rule of one over one plus 0.00215 times the difference between the two temperature profiles at each depth.", "A different set of spreads but the same set of settings, since the temperature enters the spread through the differential across the port and leaves the force balance that fixes the charge untouched.", "A different set of valves, because the same 60 degF charge lands on a different dome pressure at a different temperature and so opens at a different pressure downhole."]'::jsonb, 3, 'Two valves can share a rack opening and have nothing else in common, which is why a rack sheet without depths is not a design.'),
  ('gaslift', 'intermediate', 'final', null, 18, 'A sign off is proposed on the strength of a shut flag whose closing surface pressure sits under a psi from the operating pressure, as deepHighPressure valve 3 does at 1313.798877081 psia against 1314.7 psia. What should be done first?', '["Accept it, because the engine reports the flag from a converged column and a margin under a psi is still a margin.", "Reject the design, since a closing surface pressure that close to the operating pressure means the valve was set on the wrong stage.", "Treat the flag as undecided and establish what moves it, since a small change in the dome, the temperature profile or the gas gravity would turn it over.", "Recompute the flag at valve depth instead, since the depth road and the surface road disagree on production operated and injection operated strings alike and the depth road is the published one."]'::jsonb, 2, 'The valve above it clears by tens of psi and the one below misses by tens more, so the string as a whole is not marginal and one row of it is.'),
  ('gaslift', 'intermediate', 'final', null, 19, 'An auditor recomputes a westTexasOil stage 3 verdict at valve depth, obtains -5.671230322 psi where the engine reported -5.355864496 psi at surface, and raises it as a discrepancy. What is the correct response?', '["The two roads carry different quantities and agree on what they are for, the verdict, which is shut on both, and the design agrees on all 8 of its stages.", "The auditor is right and the surface road is the defective one, since inverting a dome up a gas column loses the temperature at depth.", "The auditor is right that the numbers differ but wrong about which matters, because the engine reports the surface margin only as a diagnostic and takes its verdict from the depth road in every case.", "The difference is a convergence artefact of the march and shrinks with the step count."]'::jsonb, 0, 'The same stage keeps valve 2 open on both roads too, at 10.525246278 psi of depth margin against 9.554898266 psi of surface margin.'),
  ('gaslift', 'intermediate', 'final', null, 20, 'A valve sheet is issued carrying rack openings and throughputs and nothing else. Which of the two claims a setting makes cannot be checked from it?', '["Neither, since the rack opening fixes the dome by way of one over one minus R and the throughput fixes the differential the valve was evaluated at, so the pair covers both claims.", "The claim that the valve is shut once the well is on production, which needs the dome at valve temperature, the depth and a gas column inverted to surface.", "The claim that the valve opens at its stage, because the rack opening is dialled with atmosphere on the far side and therefore says nothing about any pressure at depth whatsoever.", "Both, because a sheet that omits the port catalogue leaves the selected row unreproducible, and a setting whose port cannot be identified supports no claim of either kind."]'::jsonb, 1, 'westTexasOil valve 4 opens on a rack setting of 912.433488084 psia and is judged shut by a closing surface pressure of 918.986491277 psia, two close numbers that are not the same claim.'),
  ('gaslift', 'intermediate', 'final', null, 21, 'A handover lists eight mandrels for westTexasOil but only seven rack openings, the deepest row carrying a depth, the pressures either side and a throughput. Is the sheet incomplete?', '["Yes, every mandrel in a design carries a charged valve, so a missing rack opening is the signature of a setting step that failed silently on that row.", "Yes, because an orifice still has to be checked on a rack, and its opening pressure is simply the 60 degF charge divided by one minus R with the dome term left out.", "No, and the missing row also means the deepest mandrel always passes gas, since without a dome there is nothing to hold it closed at any casing pressure.", "No, the deepest mandrel is an orifice with no dome, so it has no rack opening and no closing pressure to report."]'::jsonb, 3, 'A bottom orifice is a hole rather than a valve that always opens, and it is reported with nothing beyond a depth, two pressures and a throughput.'),
  ('gaslift', 'intermediate', 'final', null, 22, 'Two candidate designs are ranked by the width of the spread on their top valve and the wider one is recommended. What has the ranking left out?', '["The drop each valve faces at its own depth, which is the only number a spread means anything against.", "The port size, without which two spreads cannot be set beside each other, since the interval a valve holds open across is proportional to the flow area at the seat.", "The bellows area, since a spread taken on a 0.31 in2 valve and one taken on a 0.77 in2 valve are quoted on different scales and have to be normalised by R before either can be ranked against the other.", "The operating pressure, which sets the absolute level the two spreads sit on and therefore decides which of them is the larger fraction of the pressure available."]'::jsonb, 0, 'midDecrementKnifeEdge opens its top valve across 55.525309973 psi and multipoints at four stages, while deepHighPressure opens across 39.204722432 psi and raises no multipointing warning anywhere.'),
  ('gaslift', 'intermediate', 'final', null, 23, 'A string spaced on 26.75 psi per valve is clean at stages 6 and 7 and multipoints at 2 through 5, and a reviewer proposes trimming the decrement to remove the stage 5 warning. What does the trim have to accomplish?', '["It has to widen the spread at valve 4, which the decrement does not touch.", "It has to lift the stage 5 surface margin above zero, which requires a trim of the order of tens of psi per valve because the margin scales with the accumulated decrement rather than with a single stage of it.", "It has to overturn 0.149791635 psi of margin at valve depth, which happens between 26.80 and 26.90 psi per valve, while moving every depth below the top mandrel in the process.", "It has to raise the drop at valve 4 above its spread, which means increasing the decrement rather than trimming it, since a larger step spends the interval faster."]'::jsonb, 2, 'The verdict is the single most consequential boolean the design emits, and it turns on a quantity smaller than a psi on a string running at 1164.7 psia at surface.'),
  ('gaslift', 'intermediate', 'final', null, 24, 'A reviewer reads only the deepest rows of a spread column, finds them narrow, and reports the string as low risk. Which exposure has that reading missed?', '["None, since a narrow interval at depth is precisely the condition under which two valves finish up open at the same time, which is what multipointing means.", "Multipointing, which lives at the top of a string where the spreads are widest and runs out with depth.", "Reopening on a casing excursion, which is the failure the narrow deep valves carry and the one a wide top valve is protected against by its own width.", "The subcritical regime, which the deep valves sit on and which makes their spreads move with every psi of change on the production side."]'::jsonb, 1, 'Reading only the bottom of the column tells you about a valve closed hard by the operating pressure and easily reopened, and reading one row tells you about neither failure.'),
  ('gaslift', 'intermediate', 'final', null, 25, 'The narrowest looking valve on a production operated table reports -31.296561503 psi and a larger port is specified in order to widen it. What is wrong with the decision?', '["The port cannot be widened without moving the mandrel, so the spacing recursion has to be rerun before any part is ordered.", "A larger port narrows the interval rather than widening it, because R rises and the multiplier one over one minus R divides the differential rather than multiplying it.", "The reported figure was never a measurement of that valve, so a change to R, the dome and the closing pressure has been made on the strength of an artefact.", "Nothing is wrong with the direction of the change, only with its size, since the catalogue on that bellows stops at 0.75 in and the interval needed is wider than any port in it can deliver."]'::jsonb, 2, 'The spread helper is handed the production pressure as the opening side and the casing as the other, and on that well the casing runs above the tubing at every valve.'),
  ('gaslift', 'intermediate', 'final', null, 26, 'A candidate cites the equal and opposite spreads of 48.150321911 psi and -48.150321911 psi returned by one well run as an injection operated string and then as a production operated one, calling it published evidence that the sign carries an argument order. What is the flaw?', '["The magnitudes differ once R has been applied to each side in turn, so the pair is not equal and opposite and the sign is not the only thing separating them.", "The comparison is invalid because a single well cannot be run under both families, and the two runs must therefore have used different depths, different ports or both.", "The flaw is that a sign change proves only that the subtraction was performed in the other order, which is a presentational matter rather than evidence of anything about the acting fluid.", "AKASO-3 is a teaching construct with no oracle behind it, so the published evidence for the swap is the constantPressurePPO valve table instead."]'::jsonb, 3, 'Every spread of that published case is negative, from -52.249540846 psi at the first valve to -31.296561503 psi at the sixth, which is the loudest available signal that the sides are the wrong way round.'),
  ('gaslift', 'intermediate', 'final', null, 27, 'An engineer holds a stage table and a valve table for the same design and subtracts the surface decrement from each spread to work out at which stage each valve shuts. What does the method get wrong?', '["It counts too small a drop at every valve, so each one is predicted to stay open longer than it does, and the shortfall grows with depth.", "It counts too large a drop at every valve, so each one is predicted to shut a stage earlier than it does and the error grows towards the bottom of the string.", "It confuses the spread with the margin, which is the quantity that actually varies from stage to stage while the spread column simply repeats a design condition value on every row of the table.", "It ignores the transfer differential, which has to be added to the decrement before the total loss reaching a valve depth can be compared with anything."]'::jsonb, 0, 'A lower stage pressure carries a lighter gas column, so the column adds less weight over the interval and the loss arriving at depth exceeds the loss at surface.'),
  ('gaslift', 'intermediate', 'final', null, 28, 'A stage row flags two valves open at once, and the report goes on to state how the injection gas divides between them. What is wrong with the report?', '["Nothing at all, provided the two throughputs are quoted with the regime and the differential each of them was evaluated at, which is what makes a rate checkable.", "The division can be recovered from the two throughputs, but only after each has been corrected for the fact that the shallower valve is the one throttling on its stem while the deeper one is at full lift.", "The report should have divided the gas in proportion to the two spreads, since spread is the interval each valve holds open across and therefore the share of the drop each of them absorbs.", "The comparison detects the overlap and knows nothing about the division, since no injection rate exists anywhere in the module."]'::jsonb, 3, 'Both sides of the closing comparison come off shut in gas columns, so neither is the casing pressure a gauge reads while gas is moving.'),
  ('gaslift', 'intermediate', 'final', null, 29, 'A sensitivity study plots the stage 5 surface margin of midDecrementKnifeEdge against the design gas rate and returns a flat line through 400, 1000 and 1400 Mscf/d. What is the plot showing?', '["That the verdict is insensitive to the design gas rate across the range studied, which is the conclusion a flat line through three well separated points supports.", "That the same 0.25 in port was chosen at all three targets, which is the only route by which a gas rate reaches the verdict.", "That the margin depends on the gas rate through the throughput at each valve, and that the dependence is genuinely weak because the throughputs are far above the target at every one of the three points sampled.", "That the sweep was run at a fixed port, which is why the axis returned nothing, and that letting the port float would have produced the missing slope."]'::jsonb, 1, 'The margin holds 0.124769727 psi from 400 through 1400 Mscf/d and then jumps to 15.249903355 psi at 1600, where the catalogue step is crossed and an extra multipointing stage appears.'),
  ('gaslift', 'intermediate', 'final', null, 30, 'A study is commissioned to establish how close a design sits to a different multipointing verdict, given that the gas rate axis returns nothing between catalogue steps. Which sweep answers the question?', '["A finer sweep of the gas rate axis, since the flip is a step and finer sampling is how a step is located.", "A sweep over the catalogue itself, one port at a time, which returns 0.124769727 psi at 0.25 in, 15.249903355 at 0.3125 in, 33.744341944 at 0.375 in, 55.613320820 at 0.4375 in and 80.863315289 psi at 0.5 in.", "A sweep of the bellows area, since R is the quantity the verdict is downstream of and the bellows is the half of R that a catalogue does not quantise.", "A sweep of the decrement, which moves the verdict continuously and is therefore the only axis on which a margin can be differentiated at all."]'::jsonb, 1, 'The sensitivity lives in a catalogue rather than in a curve, so the sweep that finds it has to run over the mechanism and not over the axis the target is quoted on.'),
  ('gaslift', 'intermediate', 'final', null, 31, 'Every charged valve of midDecrementKnifeEdge is taken from a 0.25 in port to a 0.3125 in one because the throughput column looked tight, and every rate in the table improves. What else has the change done?', '["It has taken the stage 5 surface margin from 0.124769727 psi to 15.249903355 psi and given the string an extra multipointing stage.", "Nothing else, since the port area enters the throughput expression and the force balance by separate routes and the two consequences do not meet anywhere.", "It has narrowed every spread in the string, because a larger port raises R and R divides the differential across the port in the expression the spread comes from.", "It has moved the depths, since the port catalogue is read inside the spacing recursion and a larger selected port alters the head available to each successive mandrel."]'::jsonb, 0, 'The port sets R, which sets the dome the balance demands, which sets the closing pressure and the interval the valve stays open across, so the throughput column was improved and the design was changed.'),
  ('gaslift', 'intermediate', 'final', null, 32, 'Two valves in one string are asked to hold their rates while the tubing pressure wanders by tens of psi. Which of them can, and what settles it?', '["The deeper of the two, because the annulus column is heavier at depth and a heavier upstream column is less disturbed by a change on the other side of the port.", "The ones with the larger flow area, since area sets the rate and a large port is correspondingly less sensitive to the ratio it is operating at.", "The ones whose pressure ratio is below 0.551208318, such as valves 1 and 2 of deepHighPressure, since below it the gas leaves the port at the speed of sound and the downstream pressure cannot send information upstream.", "Neither, since the module has no flowing traverse."]'::jsonb, 2, 'The two pressures close on each other with depth, so the deep valves sit on the sensitive branch, the same pattern the spread column shows.'),
  ('gaslift', 'intermediate', 'final', null, 33, 'A throughput column and a spread column for the same string both fall steadily with depth. Is that one mechanism or two?', '["Two, since throughput falls on temperature and spread falls on R.", "Two, because the throughput column falls on the port area selected at each valve while the spread column falls on the accumulated decrement, and the two happen to run in the same direction down this particular string.", "One, the accumulated decrement, which lowers the upstream pressure at every successive valve and therefore reduces the rate and the interval together in fixed proportion.", "One, the injection and production pressures closing on each other with depth, which narrows the differential the spread is R times and lifts the ratio the rate depends on."]'::jsonb, 3, 'Every charged valve of midDecrementKnifeEdge carries the same 0.25 in port and its rates still run from 1529.098759722 down to 1347.108582683 Mscf/d.'),
  ('gaslift', 'intermediate', 'final', null, 34, 'The design gas rate on westTexasOil is doubled from its published 500.0 Mscf/d target and the valve table comes back identical. Has the run failed?', '["Yes, since the selected port is chosen to meet the target, and a target that has doubled cannot be met by a row that was picked to clear the original one.", "No, the smallest catalogue port at valve 1 already passes 1359.548519 Mscf/d, so the target can move a long way before a different row is taken.", "No, and the reason is that selectPort takes the largest port that still meets the target, so a rise in the target moves the choice downward through the catalogue rather than upward and lands on the same row.", "Yes, because a table that fails to respond to an input it declares as an input is the usual signature of a warning suppressed somewhere upstream of the valve loop."]'::jsonb, 1, 'The rule walks the catalogue upward and takes the first row that clears the target, and at that valve the candidates run to 12235.936675 Mscf/d.'),
  ('gaslift', 'intermediate', 'final', null, 35, 'A catalogue holding only a 0.125 in port is asked for 900 Mscf/d and valve 1 comes back passing 340 Mscf/d. What does the module do about it, and what does it stay silent on?', '["It raises a portTooSmall warning, and it says nothing about a design sitting one catalogue step away from a different multipointing verdict.", "It selects the port anyway without comment, and stays silent on the shortfall.", "It raises a portTooSmall warning and also flags the affected valve as subcritical, but stays silent on whether the well can accept the gas the target asks for.", "It substitutes the largest port in the catalogue and issues a warning naming the substitution, staying silent on the effect that substitution has on R and therefore on the dome."]'::jsonb, 0, 'That warning is the only guard in the port selection step, and the rate it reports is an upper bound in any case because a real valve throttles on its stem.'),
  ('gaslift', 'intermediate', 'final', null, 36, 'A design is about to be revised and the team wants to know which single input, moved slightly, will change the largest number of rows on the sheet. What is the answer, and why?', '["The bellows area, since R appears in the dome, the rack opening, the spread and the selected port.", "The gas gravity, because it sets the weight of the injection column and therefore the injection pressure at every depth in the string, which is the input every other quantity is computed from.", "The decrement, since it fixes the stage pressures, which fix the depths, which fix the temperatures and both pressures at every port, and therefore every dome and every rack setting below the top mandrel.", "The design gas rate, because it selects the port, and the port sets R, the dome, the rack opening, the spread and the closing pressure of every charged valve in the string."]'::jsonb, 2, 'The top mandrel is the one row a decrement cannot move, which is what makes it the check that something upstream of the recursion has changed.'),
  ('gaslift', 'intermediate', 'final', null, 37, 'A checker subtracts the dome at valve temperature from the injection pressure at depth on an injection operated valve and does not get the spread that the sheet reports. Whose arithmetic is at fault?', '["The checker''s, because on such a valve the two are the same number by construction, as 1068.362497529 psia less 1021.076842603 psia gives 47.285654927 psi.", "The engine''s, since the spread is computed from R and the differential across the port and the identity holds only when R is small.", "Neither, because the subtraction gives the opening interval at the design condition while the spread column carries the same interval evaluated at the operating pressure, and the two agree only at the stage the valve opens on.", "The engine''s, and the mismatch is the pinned known divergence in which the two sides of the port are handed over swapped."]'::jsonb, 0, 'That identity is what spread is rather than a check on the engine, so a mismatch is worth chasing in the arithmetic before it is reported as a defect.'),
  ('gaslift', 'intermediate', 'final', null, 38, 'A design report is returned with a request for the shortest set of additions that would make every number in it checkable by a third party. What has to be added?', '["The stop reason, the warning list and the port catalogue, which between them fix the whole design.", "The bellows against every R, the regime and the differential against every rate, and the depth and the stage against every setting.", "The oracle margins alongside the engine values, since a number cannot be checked by a third party unless the independent comparison that gated it is reproduced beside it.", "The kill fluid gradient and the unloading gradient, since those two lines are what every depth and every production pressure in the sheet was measured against."]'::jsonb, 1, 'A rate on its own cannot be compared with another valve and hides which branch of the equation produced it, and an R with no bellows named is not a number at all.'),
  ('gaslift', 'intermediate', 'final', null, 39, 'One quantity in this course settles down as the step count is raised while another does not move until an input crosses a catalogue step. What does refining prove in each case?', '["Refining proves convergence in both cases, at different rates.", "Refining proves nothing in either case, since a residual computed from the same tabulation on both sides of the comparison cannot see its own error, which is the reason the depth of the crossing is wrong while the residual looks small.", "Refining the gas column exposes a truncation of the same family as the one that afflicts the pressure march in the preceding course, and refining the gas rate axis exposes a second one in port selection.", "Refining the gas column is a real test that it passes, 20 steps and 2000 differing by 0.0036 psi at the packer, while refining the gas rate axis adds points to a dependence that is not there."]'::jsonb, 3, 'The skill is telling a truncation that refinement removes from a mechanism that has no curve in it, and the way you tell them apart is by refining and watching.'),
  ('gaslift', 'intermediate', 'final', null, 40, 'A client asks for the depth at which gas will actually enter the tubing on production and for evidence that the string unloads stage by stage. What can this tier hand over?', '["Both answers, since the multipointing warnings are the evidence that the string unloads and the deepest charged valve is the point of injection.", "Neither, since a design that has not been unloaded carries no defensible numbers at all and the settings cannot be issued until the sequence has been run.", "The depths, the settings, the spreads, the throughputs and what each of them asserts, with the walk down and the point of injection left to the tier that follows.", "The point of injection but not the unloading evidence, since the crossing of the two pressure lines is fixed once the string is spaced while the sequence needs a stage by stage march that is outside the module."]'::jsonb, 2, 'The published cases carry 28 stage rows and 85 closing margin rows of the sequence, and the margins those verdicts sit on are what the next tier is about.'),
  ('gaslift', 'intermediate', 'final', null, 41, 'Before any arithmetic is done on a graded design, the inputs are sorted into a spacing list and a valve list. What does the sorting buy?', '["It catches a pressure quoted on the wrong datum and settles which inputs can move a depth at all, since the bellows area, the port catalogue and the design gas rate cannot.", "It fixes the order the two halves are computed in, which is otherwise ambiguous.", "It separates the inputs the engine derives from those the caller supplies, which is what determines which of them can be varied in a sensitivity study without rerunning the spacing recursion.", "It identifies which inputs carry a warning of their own, so that the warning list can be read against them once the run has finished and any silent stop can be attributed."]'::jsonb, 0, 'The spacing list holds the two operating pressures, the wellhead pressure, the two gradients, the transfer differential, the decrement and the method, and every pressure in it is psia.'),
  ('gaslift', 'intermediate', 'final', null, 42, 'A review is handed a page of booleans: shut flags, pass flags and multipointing warnings. What should be asked about each?', '["Which routine emitted it, so that the pinned known divergences can be excluded.", "Whether the oracle agreed with it, since verdict agreement is recorded case by case and a boolean the independent comparison never reached carries no weight of its own.", "The stage it was evaluated at, since a flag read at the wrong stage is the most common way a correct calculation reaches a wrong conclusion about a valve.", "The number behind it and how much room that number had, since a verdict resting on a fraction of a psi is not the same result as one clearing by tens."]'::jsonb, 3, 'The stage 5 verdict on the published knife edge case clears by 0.124769727 psi at surface, and the same design clears other stages by tens of psi.');
